UIDustParticle=function(game,x,y,key,frame){Phaser.Particle.call(this,game,x,y,key,frame);this.fadeSpeed=0.018-Math.random()*0.009;this.kill();};UIDustParticle.prototype=Object.create(Phaser.Particle.prototype);UIDustParticle.prototype.constructor=UIDustParticle;UIDustParticle.prototype.onEmit=function(){this.body.x+=this.body.velocity.x*(Math.random()*6.0+1.0)/15.0;this.body.y+=this.body.velocity.y*(Math.random()*6.0+1.0)/15.0;};UIDustParticle.prototype.update=function(){this.alpha-=this.fadeSpeed;this.scale.x+=0.0083;this.scale.y+=0.0083;};UIDustParticle.prototype.retire=function(){this.kill();};